<template><main class="page-width checkout-page"><div class="page-title"><span class="eyebrow">ALMOST THERE</span><h1>Checkout</h1><p>Just a few details and your basket is on its way.</p></div><div v-if="!store.cartItems.length" class="empty">Your basket is empty. <router-link to="/shop">Browse the market</router-link></div><form v-else class="checkout-grid" @submit.prevent="placeOrder"><section class="checkout-form"><div class="form-card"><h2><span>01</span> Delivery details</h2><div class="fields"><label>Full name<input v-model="form.name" required placeholder="Your name"></label><label>Email address<input v-model="form.email" type="email" required placeholder="you@example.com"></label><label>Phone number<input v-model="form.phone" type="tel" required placeholder="+234"></label><label>City<input v-model="form.city" required placeholder="Your city"></label><label class="wide">Delivery address<textarea v-model="form.address" required rows="3" placeholder="House number, street and area"></textarea></label></div></div><div class="form-card"><h2><span>02</span> Payment method</h2><label class="payment-option"><input v-model="form.payment" type="radio" value="paystack"> <b>Pay online with Paystack</b><small>Card, bank transfer and USSD (integration required)</small></label><label class="payment-option"><input v-model="form.payment" type="radio" value="flutterwave"> <b>Flutterwave</b><small>Pay securely with supported local methods</small></label><label class="payment-option"><input v-model="form.payment" type="radio" value="delivery"> <b>Pay on delivery</b><small>Pay when your order arrives</small></label><p v-if="paymentError" class="payment-error">{{ paymentError }}</p></div></section><aside class="order-summary"><h2>Your order</h2><div v-for="item in store.cartItems" :key="item.id" class="order-line"><span>{{ item.name }} × {{ item.quantity }}</span><b>${{ (item.price*item.quantity).toFixed(2) }}</b></div><div class="order-line"><span>Delivery</span><b>{{ store.cartTotal>=50?'FREE':'$4.99' }}</b></div><div class="grand-total"><span>Total</span><b>${{ (store.cartTotal+(store.cartTotal>=50?0:4.99)).toFixed(2) }}</b></div><button class="place-order" :disabled="busy">{{ busy ? 'Placing order…' : 'Place order' }} <Icon icon="mdi:arrow-right"/></button><p class="secure"><Icon icon="mdi:lock-outline"/> Your details are kept private and secure.</p></aside></form></main></template>
<script setup>
import { reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { useAllProductStore } from '@/stores/useAllProductStore'
import { useOrdersStore } from '@/stores/orders'
const store=useAllProductStore(), orders=useOrdersStore(), router=useRouter()
const busy=ref(false),paymentError=ref('')
const form=reactive({name:'',email:'',phone:'',city:'',address:'',payment:'paystack'})
function placeOrder(){if(form.payment!=='delivery'){paymentError.value='Online payments are not connected yet. Configure your Paystack or Flutterwave keys and server-side verification, or choose Pay on delivery for this demo.';return}paymentError.value='';busy.value=true;const total=store.cartTotal+(store.cartTotal>=50?0:4.99);const order=orders.place({customer:{...form},items:store.cartItems.map(i=>({...i})),total,paymentMethod:form.payment});store.clearCart();router.push({path:'/order-confirmation',query:{id:order.id}})}
</script>
